import pandas as pd
import numpy as np
import os

# -------------------------------------------------------------------
# 1. Configuration & Reproducibility
# -------------------------------------------------------------------
SEED = 42
rng = np.random.default_rng(SEED)

# Define output directory (compatible with Google Colab / local)
OUTPUT_DIR = "/content" if os.path.exists("/content") else "."
CSV_PATH = os.path.join(OUTPUT_DIR, "starbucks_synthetic_transactions.csv")
PARQUET_PATH = os.path.join(OUTPUT_DIR, "starbucks_synthetic_transactions.parquet")

# -------------------------------------------------------------------
# 2. Dimension Generation (Store, Date, Category)
# -------------------------------------------------------------------
# Dates: 2 Years (730 days)
dates = pd.date_range(start="2022-01-01", periods=730, freq="D")
df_dates = pd.DataFrame({"date": dates})
df_dates["is_weekend"] = df_dates["date"].dt.dayofweek.isin([5, 6]).astype(int)

# Stores: 50 Locations
store_ids = [f"STORE_{str(i).zfill(3)}" for i in range(1, 51)]
market_segments = rng.choice(["Urban", "Suburban", "Rural"], size=50, p=[0.4, 0.4, 0.2])
df_stores = pd.DataFrame({
    "store_id": store_ids,
    "market_segment": market_segments
})

# Categories: 3 Core Product Lines with distinct economic profiles
df_categories = pd.DataFrame({
    "category": ["Frappuccino", "Drip Coffee", "Bakery"],
    "base_price": [5.50, 3.00, 4.00],
    "unit_cost": [1.50, 0.50, 1.20],
    "base_volume": [100, 200, 150],
    "elasticity": [-2.0, -0.8, -1.5] # Negative elasticity dictates demand response to price drops
})

# Promotions: The 3-Tier Treatment Architecture
df_promotions = pd.DataFrame({
    "promo_id": ["PROMO_NONE", "HAPPY_HOUR_20", "PROMO_33"],
    "treatment_group": ["CONTROL", "PROMO_20", "PROMO_33"],
    "discount_pct": [0.00, 0.20, 0.33]
})

# -------------------------------------------------------------------
# 3. Vectorized Base DataFrame Construction
# -------------------------------------------------------------------
# Creates the 109,500 row grain: Store x Date x Category
df_base = df_dates.merge(df_stores, how="cross").merge(df_categories, how="cross")

# -------------------------------------------------------------------
# 4. Confounded Treatment Assignment (The Causal Mechanism)
# -------------------------------------------------------------------
# Urban stores have a 60% chance of promotion; others 30%.
# This introduces the intentional selection bias needed for the portfolio.
df_store_day = df_base[["store_id", "date", "market_segment"]].drop_duplicates()

df_store_day["promo_prob"] = np.where(df_store_day["market_segment"] == "Urban", 0.60, 0.30)
df_store_day["is_promo_day"] = rng.random(len(df_store_day)) < df_store_day["promo_prob"]

# If it is a promo day, randomly assign between the 20% and 33% discount
active_promos = ["HAPPY_HOUR_20", "PROMO_33"]
df_store_day["assigned_promo"] = rng.choice(active_promos, size=len(df_store_day))

df_store_day["promo_id"] = np.where(
    df_store_day["is_promo_day"],
    df_store_day["assigned_promo"],
    "PROMO_NONE"
)

# Merge treatment assignments back to the base grain
df_base = df_base.merge(
    df_store_day[["store_id", "date", "promo_id"]],
    on=["store_id", "date"],
    how="left"
)
df_base = df_base.merge(df_promotions, on="promo_id", how="left")

# -------------------------------------------------------------------
# 5. Demand Generation & Financial Calculations
# -------------------------------------------------------------------
# Generative Variables (Environmental Noise & Covariates)
df_base["weather_effect"] = rng.normal(1.0, 0.05, len(df_base))
df_base["day_effect"] = np.where(df_base["is_weekend"] == 1, 1.25, 1.0)
df_base["noise"] = rng.normal(1.0, 0.10, len(df_base))

# Elasticity impact: percentage change in quantity demanded
# Formula proxy: 1 + (Elasticity * % Change in Price)
df_base["price_change_effect"] = 1 + (df_base["elasticity"] * -df_base["discount_pct"])

# Calculate Volume
df_base["expected_volume"] = (
    df_base["base_volume"] *
    df_base["day_effect"] *
    df_base["weather_effect"] *
    df_base["price_change_effect"]
)
df_base["units_sold"] = np.maximum(0, np.round(df_base["expected_volume"] * df_base["noise"])).astype(int)

# Financial Accounting
df_base["gross_revenue"] = df_base["units_sold"] * df_base["base_price"]
df_base["net_revenue"] = df_base["units_sold"] * (df_base["base_price"] * (1 - df_base["discount_pct"]))
df_base["total_cogs"] = df_base["units_sold"] * df_base["unit_cost"]
df_base["profit"] = df_base["net_revenue"] - df_base["total_cogs"]

# Safe division for profit margin
df_base["profit_margin_pct"] = np.where(
    df_base["net_revenue"] > 0,
    df_base["profit"] / df_base["net_revenue"],
    0.0
)

# -------------------------------------------------------------------
# 6. Column Organization
# -------------------------------------------------------------------
final_columns = [
    "date", "store_id", "market_segment", "category",
    "treatment_group", "promo_id", "discount_pct",
    "base_price", "unit_cost", "elasticity",
    "weather_effect", "price_change_effect", "expected_volume",
    "units_sold", "gross_revenue", "net_revenue",
    "total_cogs", "profit", "profit_margin_pct"
]
df_final = df_base[final_columns].copy()

# -------------------------------------------------------------------
# 7. Automated Data Quality Assurance
# -------------------------------------------------------------------
print("Executing Automated QA Validation...")
assert len(df_final) == 109500, f"Error: Expected 109,500 rows, got {len(df_final)}"
assert df_final.isnull().sum().sum() == 0, "Error: Null values detected in dataset."

# Reconcile Financials
sample_net = df_final["net_revenue"].iloc[0]
sample_cogs = df_final["total_cogs"].iloc[0]
sample_profit = df_final["profit"].iloc[0]
assert np.isclose(sample_net - sample_cogs, sample_profit), "Error: Profit reconciliation failed."

print("QA Passed. Dataset is mathematically sound.")

# -------------------------------------------------------------------
# 8. Export to CSV and Parquet
# -------------------------------------------------------------------
df_final.to_csv(CSV_PATH, index=False)
df_final.to_parquet(
    PARQUET_PATH,
    index=False,
    engine="pyarrow",
    compression="snappy"
)

