import pymc as pm
import arviz as az
import pandas as pd
import numpy as np

# Filter out categories that might not have enough data points or variability for modeling
# For simplicity, we'll proceed with the current df_elasticity, but in a real scenario,
# a minimum number of unique price points per category would be a good check.

# Create a mapping for categories to integers for PyMC
categories = df_elasticity['category'].unique()
category_idx = pd.Categorical(df_elasticity['category'], categories=categories).codes
n_categories = len(categories)

# Define the hierarchical Bayesian model with updated priors
with pm.Model() as elasticity_model:
    # Priors for the global (hyper)parameters
    mu_intercept = pm.Normal('mu_intercept', mu=0, sigma=10)
    # FIX: Changed HalfCauchy to HalfNormal for safer sampling
    sigma_intercept = pm.HalfNormal('sigma_intercept', sigma=5)

    mu_elasticity = pm.Normal('mu_elasticity', mu=0, sigma=2)
    # FIX: Changed HalfCauchy to HalfNormal
    sigma_elasticity = pm.HalfNormal('sigma_elasticity', sigma=2)

    # Non-centered reparameterization for category-specific intercepts
    intercept_offset = pm.Normal('intercept_offset', mu=0, sigma=1, shape=n_categories)
    intercept = pm.Deterministic('intercept', mu_intercept + intercept_offset * sigma_intercept)

    # Non-centered reparameterization for category-specific elasticities
    elasticity_offset = pm.Normal('elasticity_offset', mu=0, sigma=1, shape=n_categories)
    elasticity = pm.Deterministic('elasticity', mu_elasticity + elasticity_offset * sigma_elasticity)

    # FIX: Changed HalfCauchy to HalfNormal for the global error term
    sigma = pm.HalfNormal('sigma', sigma=1)

    # Expected value of log_units_sold (linear regression equation)
    # log(units_sold) = intercept + elasticity * log(price)
    mu = intercept[category_idx] + elasticity[category_idx] * df_elasticity['log_price'].values

    # Likelihood function: observed log_units_sold
    log_units_sold_obs = pm.Normal('log_units_sold_obs', mu=mu, sigma=sigma, observed=df_elasticity['log_units_sold'].values)

    # Sample from the posterior distribution
    trace = pm.sample(2000, tune=2000, cores=2, target_accept=0.999, random_seed=42, max_treedepth=15)

# Display summary statistics of the posterior distributions to capture divergences
summary_stats = az.summary(trace, var_names=['mu_intercept', 'sigma_intercept', 'mu_elasticity', 'sigma_elasticity', 'intercept', 'elasticity', 'sigma'], filter_vars="regex")

# Check for divergences after sampling
if summary_stats['n_divergences'].sum() == 0:
    print("Bayesian elasticity model defined and sampled successfully without divergences!")
else:
    print(f"Bayesian elasticity model defined and sampled. However, {summary_stats['n_divergences'].sum()} divergences were found.")

# Store the trace and model for later analysis
