print("\nPosterior summary for model parameters:")
display(summary_stats)

# Display category-specific elasticity estimates
print("\nCategory-specific elasticity estimates:")
elasticity_estimates = summary_stats.loc[summary_stats.index.str.contains(r'elasticity\[')]
elasticity_estimates = elasticity_estimates.reset_index()
elasticity_estimates['category'] = elasticity_estimates['index'].apply(lambda x: categories[int(x.split('[')[1].split(']')[0])])
elasticity_estimates = elasticity_estimates[['category', 'mean', 'sd', 'hdi_3%', 'hdi_97%']]
elasticity_estimates = elasticity_estimates.rename(columns={'mean': 'elasticity_mean', 'sd': 'elasticity_sd'})
display(elasticity_estimates.sort_values('elasticity_mean'))

