import pandas as pd
import numpy as np

# Calculate the actual price paid after discount
df_analytics['price_point'] = df_analytics['base_price'] * (1 - df_analytics['discount_pct'])

# Aggregate data by category and price point to observe demand at different prices
# We'll use the mean of daily units sold and daily net revenue as our demand proxies
df_elasticity = df_analytics.groupby(['category', 'price_point'], as_index=False).agg(
    daily_units_sold=('daily_units_sold', 'mean'),
    daily_net_revenue=('daily_net_revenue', 'mean'),
    base_price=('base_price', 'first'),
    discount_pct=('discount_pct', 'first')
)

# Ensure units_sold is integer type after aggregation if needed, or handle as float
df_elasticity['daily_units_sold'] = df_elasticity['daily_units_sold'].astype(int)

# Log transform for modeling linear relationship in Bayesian regression
df_elasticity['log_price'] = np.log(df_elasticity['price_point'])
df_elasticity['log_units_sold'] = np.log(df_elasticity['daily_units_sold'] + 1e-6) # Add small epsilon to avoid log(0)

